import React, { useState, useEffect } from 'react';
import '../styles/Calendar.css';

function CalendarView({ token }) {
  const [events, setEvents] = useState([]);
  const [currentDate, setCurrentDate] = useState(new Date());

  useEffect(() => {
    fetchEvents();
  }, [token]);

  const fetchEvents = async () => {
    try {
      const response = await fetch('/api/events', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json();
      setEvents(data);
    } catch (error) {
      console.error('Error fetching events:', error);
    }
  };

  // --- Calendar Logic ---
  const startOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
  const endOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0);
  const startDay = startOfMonth.getDay(); // 0 (Sun) to 6 (Sat)
  const daysInMonth = endOfMonth.getDate();

  const prevMonthEnd = new Date(currentDate.getFullYear(), currentDate.getMonth(), 0).getDate();
  
  const days = [];
  // 1. Fill previous month's padding
  for (let i = startDay - 1; i >= 0; i--) {
    days.push({ day: prevMonthEnd - i, currentMonth: false });
  }
  // 2. Fill current month
  for (let i = 1; i <= daysInMonth; i++) {
    days.push({ day: i, currentMonth: true });
  }
  // 3. Fill next month's padding
  const remaining = 42 - days.length; // Keep a consistent 6-row grid
  for (let i = 1; i <= remaining; i++) {
    days.push({ day: i, currentMonth: false });
  }

  const isToday = (day) => {
    const today = new Date();
    return day === today.getDate() && 
           currentDate.getMonth() === today.getMonth() && 
           currentDate.getFullYear() === today.getFullYear();
  };

  return (
    <div className="calendar-container">
      <div className="calendar-header">
        <h2 style={{ margin: 0 }}>
          {currentDate.toLocaleString('default', { month: 'long' })} {currentDate.getFullYear()}
        </h2>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button onClick={() => setCurrentDate(new Date(currentDate.setMonth(currentDate.getMonth() - 1)))}>Prev</button>
          <button onClick={() => setCurrentDate(new Date())}>Today</button>
          <button onClick={() => setCurrentDate(new Date(currentDate.setMonth(currentDate.getMonth() + 1)))}>Next</button>
        </div>
      </div>

      <div className="calendar-grid">
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(d => (
          <div key={d} className="calendar-day-label">{d}</div>
        ))}
        {days.map((item, idx) => {
          // Check for events on this specific date
          const dateString = `${currentDate.getFullYear()}-${(currentDate.getMonth() + 1).toString().padStart(2, '0')}-${item.day.toString().padStart(2, '0')}`;
          const dayEvents = item.currentMonth ? events.filter(e => e.event_date === dateString) : [];

          return (
            <div key={idx} className={`calendar-cell ${!item.currentMonth ? 'different-month' : ''} ${item.currentMonth && isToday(item.day) ? 'today' : ''}`}>
              <div className="day-number">{item.day}</div>
              {dayEvents.map(e => (
                <div key={e.id} className={`event-dot ${e.type}`}>
                  {e.title}
                </div>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default CalendarView;
